('advanced-native-013', '["phrase"]'::jsonb, '{"advanced-native-013-v1-audio":{"type":"mc","answers":["The noise leaves the speaker feeling tired."],"options":["The noise leaves the speaker feeling tired.","The speaker is mainly worried about making a poor impression.","The speaker feels busier but just as refreshed.","The speaker has lost interest in the job itself."]},"advanced-native-013-v2-reply":{"type":"mc","answers":["I spend the whole afternoon focusing on the talks.","The long meetings drain my energy.","They go on for hours without a break.","Following several discussions at once is exhausting."],"options":["I spend the whole afternoon focusing on the talks.","The long meetings drain my energy.","They go on for hours without a break.","Following several discussions at once is exhausting."]},"advanced-native-013-v1-scene":{"type":"mc","answers":["The late nights are draining my energy."],"options":["The late nights are draining my energy.","I have lost interest in my report and do not want to finish it.","I am mainly frustrated because my brother ignores my advice."]},"advanced-native-013-v1-contrast":{"type":"mc","answers":["A short walk leaves the students refreshed and ready to study."],"options":["A short walk leaves the students refreshed and ready to study.","Volunteers feel worn out after answering calls for six hours.","Repeated arguments leave the team mentally exhausted."]},"advanced-native-013-v1-branch":{"type":"mc","answers":["It may still drain your energy. Could you take a day off?"],"options":["Feeling tired proves that the project is pointless.","If you enjoy it, it cannot possibly make you tired.","It may still drain your energy. Could you take a day off?"]},"advanced-native-013-v1-final":{"type":"open","answers":["Studying in a noisy room drains her energy. She could try the library tomorrow.","The constant noise is draining her energy, so she should find a quieter place to study."],"options":[]}}'::jsonb),
('advanced-native-014', '["phrase"]'::jsonb, '{"advanced-native-014-v1-audio":{"type":"mc","answers":["Repeated manageable efforts help confidence grow."],"options":["Repeated manageable efforts help confidence grow.","Taking on the hardest challenge immediately is the fastest route.","Confidence grows mainly through physical fitness.","One enormous effort always replaces regular practice."]},"advanced-native-014-v2-reply":{"type":"mc","answers":["Short daily sessions are easier for me to maintain.","I remember the skills better when I use them often.","A steady routine helps me build confidence gradually.","It is like exercise: a little regular practice helps me improve."],"options":["Short daily sessions are easier for me to maintain.","I remember the skills better when I use them often.","A steady routine helps me build confidence gradually.","It is like exercise: a little regular practice helps me improve."]},"advanced-native-014-v1-scene":{"type":"mc","answers":["Problem-solving is like exercise: start gently and increase the difficulty gradually."],"options":["Problem-solving is like exercise: natural talent matters more than guided practice.","Problem-solving is like exercise: start gently and increase the difficulty gradually.","Problem-solving is like exercise: you should begin with the hardest task to make faster progress."]},"advanced-native-014-v1-contrast":{"type":"mc","answers":["Every feature of physical training must also apply to learning."],"options":["Every feature of physical training must also apply to learning.","The writer should explain the similarity.","Both activities may need regular practice."]},"advanced-native-014-v1-branch":{"type":"mc","answers":["Writing is like exercise: regular practice builds skill over time."],"options":["Writing is like exercise: regular practice builds skill over time.","Writing is like exercise: one very long session should replace a regular habit.","Writing improves as soon as you buy the right equipment."]},