('advanced-native-015', '["phrase"]'::jsonb, '{"advanced-native-015-v1-audio":{"type":"mc","answers":["The plan could cause harm beyond ordinary tiredness."],"options":["The person has already decided to leave the team.","The plan could cause harm beyond ordinary tiredness.","Feeling tired always proves that an injury has occurred.","The plan is described as completely safe for everyone."]},"advanced-native-015-v2-reply":{"type":"mc","answers":["It gives beginners no time to recover.","I am concerned that the workload is beyond their limits.","It could leave you injured instead of helping you improve.","We need a safer plan that beginners can manage."],"options":["It gives beginners no time to recover.","I am concerned that the workload is beyond their limits.","It could leave you injured instead of helping you improve.","We need a safer plan that beginners can manage."]},"advanced-native-015-v1-scene":{"type":"mc","answers":["Just as excessive training can leave you injured, an impossible workload can cause lasting harm."],"options":["Just as excessive training can leave you injured, an impossible workload can cause lasting harm.","Being tired after any task proves that you have been injured.","Every challenge causes exactly the same harm as a physical accident."]},"advanced-native-015-v1-contrast":{"type":"mc","answers":["A short rehearsal makes you slightly tired, with no harm or injury described."],"options":["A short rehearsal makes you slightly tired, with no harm or injury described.","An accident during a match causes a physical injury.","A writer explicitly compares lasting emotional harm with a wound."]},"advanced-native-015-v1-branch":{"type":"mc","answers":["Not necessarily. A task can make you tired without leaving you injured."],"options":["Yes. Injured and tired mean exactly the same thing.","Injured means that you decided to leave the place.","Not necessarily. A task can make you tired without leaving you injured."]},"advanced-native-015-v1-final":{"